import{z as o,x as d,o as E,c as B,q as n,j as s,D as e,d as l,s as i,S as A,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"LLM 裁判偏差","description":"","frontmatter":{"title":"LLM 裁判偏差","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/llm-judge-bias.md","filePath":"llm/llm-judge-bias.md","lastUpdated":1791063341000}'),m={name:"llm/llm-judge-bias.md"};function p(h,a,u,D,c,_){const t=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=n('<h1 id="llm-裁判偏差" tabindex="-1">LLM 裁判偏差 <a class="header-anchor" href="#llm-裁判偏差" aria-label="Permalink to &quot;LLM 裁判偏差&quot;">​</a></h1><div class="epigraph"><p>用强模型给弱模型打分，便宜、可复现，也继承位置、长度与自我偏好。未经人校准的法官不是金标。</p><footer>—— Zheng 等, Judging LLM-as-a-Judge with MT-Bench and Chatbot Arena</footer></div><p><a href="/llm/model-cards">上一课</a>把开放生成的分数留给「谁来判」。本单元从 LLM 裁判开始。主干已有<a href="/llm/llm-judge-reward">裁判作奖励</a>与<a href="/llm/human-vs-auto-eval">人机评测分工</a>；本课补评测进阶里的偏差清单，不把法官再介绍一遍。缺口是：榜上的胜率常常是偏差的函数。后课成对对逐点默认偏差先被当成系统误差。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Zheng 等人在 MT-Bench 上量过：同一对回复，先呈现的更容易赢（位置偏差）；更长的更容易赢；法官偏爱同族模型的文风（自我增强）。这些偏差在 AlpacaEval、自动 Arena 里同样出现。开发期用法官当烟雾合法；论文主表用未交换顺序、未控制长度的法官分，则是测量失效。<span class="marginnote">位置偏差就是「先入为主」：法官先读完 A 再读 B，打分时 A 已经占据了记忆的锚点。人类评委同样如此——先端上桌的菜常占便宜，所以正经比赛都要换序再评一次，模型法官没有例外。</span></p><p>法官还有任务失效：有标准答案的数学与代码，应用程序判，不应用法官「看起来对」。难题上法官自己会幻觉，方差大于被评模型的差。</p><p><span class="marginnote">裁判提示里写「忽略长度」几乎无效。要用交换位置、长度归一或风格控制（后课），不能靠自然语言禁令。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成对评测：每个样本交换 \\(y_a,y_b\\) 跑两次，不一致则平局。报告与人评的一致率、Cohen \\(\\kappa\\) 或胜负相关，而不是只报法官 Elo。点分 Likert 更便宜、校准更差，只适合粗过滤。法官模型版本与温度写入协议，与 harness 哈希同等重要。</p>',9)),(E(),s(A,null,{default:e(()=>[i(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAIR%5B%22%E5%9B%9E%E5%A4%8D%E5%AF%B9%22%5D%20--%3E%20J%5B%22%E6%B3%95%E5%AE%98%E6%8F%90%E7%A4%BA%22%5D%0A%20%20J%20--%3E%20SWAP%5B%22%E6%8D%A2%E5%BA%8F%22%5D%0A%20%20SWAP%20--%3E%20AGR%5B%22%E4%B8%80%E8%87%B4%E5%88%99%E8%AE%B0%E8%83%9C%22%5D%0A%20%20J%20--%3E%20BIAS%5B%22%E4%BD%8D%E7%BD%AE%20%2F%20%E9%95%BF%E5%BA%A6%20%2F%20%E6%97%8F%E8%B0%B1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[l("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"法官是另一个语言模型，先验来自「什么样的回答像好助手」：列表、礼貌、自信、英语流利。位置偏差来自条件顺序改变注意力与「先完整后挑剔」的叙事习惯。自我偏好来自风格重叠：同族解码器的 n-gram 与结构更像法官的预训练。偏差进入名次后，策略会向法官审美拟合，看起来像产品进步。",-1)),(E(),s(A,null,{default:e(()=>[i(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20J%5B%22%E6%B3%95%E5%AE%98%E6%8C%89%E5%81%8F%E5%A5%BD%E6%89%93%E5%88%86%EF%BC%9A%E5%81%8F%E9%95%BF%20%2F%20%E5%81%8F%E9%9D%A0%E5%89%8D%20%2F%20%E5%81%8F%E5%90%8C%E6%97%8F%22%5D%20--%3E%20LEAD%5B%22%E5%B8%A6%E5%81%8F%E5%B7%AE%E7%9A%84%E8%83%9C%E7%8E%87%E8%BF%9B%E5%85%A5%E6%A6%9C%E5%8D%95%22%5D%0A%20%20LEAD%20--%3E%20SEL%5B%22%E5%9B%A2%E9%98%9F%E6%8C%89%E6%A6%9C%E5%8D%95%E9%80%89%E6%A8%A1%E5%9E%8B%E3%80%81%E8%B0%83%E6%8F%90%E7%A4%BA%22%5D%0A%20%20SEL%20--%3E%20FIT%5B%22%E8%BE%93%E5%87%BA%E5%90%91%E6%B3%95%E5%AE%98%E5%AE%A1%E7%BE%8E%E6%8B%9F%E5%90%88%22%5D%0A%20%20FIT%20--%3E%20LOOP%5B%22%E6%9B%B4%E5%83%8F%E5%A5%BD%E5%8A%A9%E6%89%8B%EF%BC%8C%E4%B8%8D%E7%AD%89%E4%BA%8E%E6%9B%B4%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20LOOP%20--%3E%20LEAD%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">自我偏好可以类比「老乡见老乡」：同家族模型共享预训练语料和说话习惯，连用词的 n-gram 都更像法官自己写的，读起来自然顺眼。但顺眼是风格信号，不是正确性信号——判卷人偏爱和自己笔迹像的答卷，不说明那份答卷对。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给「如何骗过法官」的提示。下一课把成对与逐点当作两种仪器，而不是两种文风。<span class="marginnote">常见误区：把「法官与 GPT-4 一致率 90%」当成法官可信的证明。两个同样偏长的评委也会高度一致——一致率高可能只是共享同一套偏差。要看的是在换序、控长这些去偏协议下与人评的一致率。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LLM 法官必须换序、对人校准；未校准者不能当主表。</li><li>位置、长度、同族偏好是一等系统误差。</li><li>可程序判定的任务不要用法官。</li><li>出处：Zheng 等 MT-Bench / LLM-as-a-Judge。</li></ul>',5))])}const F=o(m,[["render",p]]);export{f as __pageData,F as default};
